import { readFileSync } from 'node:fs';

const GATEWAY = process.env.CAPTCHA_GATEWAY_URL || 'http://127.0.0.1:3425/v1/chat/completions';
const MODEL = 'auto/deepseek-v4.1-flash';
const PROMPT = '识别图片验证码。若为算术式(如 5+4=?)计算并只输出结果；若为文本型验证码只输出字符本身。不要任何其他文字。';

const b64in = readFileSync(process.argv[2], 'utf8').trim().replace(/^data:[^,]*,/, '');
const url = 'data:image/gif;base64,' + b64in;
const resp = await fetch(GATEWAY, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + (process.env.MAGPIE_GATEWAY_KEY || 'magpie') },
  body: JSON.stringify({
    model: MODEL,
    messages: [{ role: 'user', content: [ { type: 'text', text: PROMPT }, { type: 'image_url', image_url: { url } } ] }]
  })
});
if (!resp.ok) { console.error('HTTP ' + resp.status); process.exit(1); }
const data = await resp.json();
const raw = (data?.choices?.[0]?.message?.content ?? '').trim();
console.log(raw);

